// Newly authored concept experiments. These are deterministic teaching models, not live targets.
// Row: title | controlled change | observed evidence | mechanism | failed-probe explanation | transfer question
import catalog from '../data/catalog.js'
import { advancedRows } from './advanced-content.js'
import { preparationMap } from './preparation-map.js'
const sections = [
['groundwork','00','Understand the web','Follow a request before trying to break it.',['foundations','encoding','investigation']],
['discovery','01','Find the trust boundaries','Learn what the application believes about you.',['information-disclosure','path-traversal','access-control','authentication','business-logic']],
['backend','02','Follow input into the server','Separate data from instructions.',['sql-injection','nosql-injection','command-injection','ssrf','xxe','ssti']],
['browser','03','Think like a browser','Origins, parsers, and actions in another session.',['xss','dom','csrf','cors','clickjacking','websockets']],
['applications','04','Unpack modern applications','Tokens, APIs, objects, files, and agents.',['api-testing','graphql','oauth','jwt','file-upload','deserialization','prototype-pollution','llm']],
['infrastructure','05','Question the infrastructure','Find disagreements in routing, caching, and time.',['host-header','cache-poisoning','cache-deception','request-smuggling','race-conditions']],
['fieldwork','06','Investigate without a label','Choose tests, connect evidence, and explain impact.',['essential-skills','fieldcraft']]
]
export const stages = sections.map(([id,number,title,description,ids])=>({id,number,title,description,ids}))
const content = {
foundations: [`Web requests & sessions`,`A request is an order slip, and the response is what the kitchen sends back. A session cookie is your coat-check ticket: whoever holds it may be treated as you.`,
`Read a request|Change GET /items/7 to GET /items/8; keep every header fixed.|The item changes; the session and response format stay the same.|The path selects a resource. Headers carry metadata; a body carries submitted data. A 200 response is an HTTP success, not proof of authorization.|Changing a screen label without changing the request cannot test the server.|If a page is hidden in the menu, what direct request would test whether it is protected?`,
`Cookies and identity|Replay GET /account once with Cookie: session=alice and once without it.|The first response contains Alice's profile; the second redirects to login.|HTTP has no built-in memory of a login. The server associates a session identifier with account state. Copying a cookie copies that credential until it expires or is revoked.|A cookie named role does not necessarily control authorization; inspect what the server actually trusts.|How would you distinguish an expired session from an access-control denial?`,
`Origins and sites|Compare https://shop.example.test with https://pay.example.test.|They are different origins but normally the same schemeful site.|An origin is scheme + host + port. A site usually groups subdomains under a registrable domain with the scheme. CORS uses origins; SameSite cookies use sites.|A sibling subdomain is not automatically cross-site. SameSite alone cannot protect every cross-origin request.|Why might a sibling subdomain matter to a CSRF investigation?`,
`Replay with a proxy|Send a captured POST to Repeater; change just quantity=1 to quantity=2.|A fresh server response shows whether the submitted field changes the order.|A proxy intercepts browser traffic. Repeater resends one request; Intruder automates variations. Keep a baseline, a mutation, and a response diff.|A cached page or a stale CSRF token can make a valid test appear to fail.|Which headers and token values need refreshing before comparing two requests?`,
`State and workflows|Submit checkout confirmation before creating a cart.|The model rejects the request because no valid cart state exists.|A workflow is a sequence of server-side state transitions. UI buttons suggest the sequence, but the server must enforce it independently.|Repeating a request after its one-use token is spent tests token reuse, not the original workflow.|Which earlier step sets the state consumed by the final confirmation?`],
encoding: [`Encoding & parser boundaries`,`An encoded message is a parcel wrapped for delivery, not a locked safe. Each system may unwrap one layer and hand the contents to another reader.`,
`Decode in the right order|Send path=%252e%252e%252fnotes.txt through two URL decoders.|First decode: %2e%2e%2fnotes.txt. Second decode: ../notes.txt.|Percent encoding represents bytes. Validation before a later decoding step can inspect different characters from those used by the file loader.|Double encoding has no magic power when the application decodes only once.|Where must path validation happen if routing and file access decode differently?`,
`Base64 is a representation|Decode eyJyb2xlIjoidXNlciJ9.|The bytes are {"role":"user"}; no secret key was needed.|Base64 maps bytes to printable text. Base64url changes the alphabet and commonly omits padding. Neither supplies integrity or confidentiality.|Editing a signed token's decoded content normally breaks its signature.|What extra check turns a readable token into a tamper-resistant token?`,
`HTML versus JavaScript|Place a quote into an HTML attribute and then into a JavaScript string.|The same character reaches two different parser rules.|HTML entity encoding protects particular HTML contexts. JavaScript string escaping, URL validation, and safe DOM APIs address different contexts.|Escaping quotes cannot make a javascript: URL safe. One universal sanitizer is insufficient.|Which parser sees the value next, and what makes a value become instructions there?`,
`Types and duplicate keys|Compare {"count":1}, {"count":"1"}, and count=1&count=9.|Different parsers may preserve a number, coerce a string, or choose different duplicate values.|A request can pass through several parsers. Type conversion and first-versus-last duplicate handling create disagreements worth testing.|A different error proves a parser difference, not an exploitable security impact.|How can you show that validation sees one value while the action uses another?`],
investigation: [`Your investigation loop`,`Be a detective running small experiments, not a person trying every key on a ring. A useful clue changes what you will test next.`,
`Build a clean baseline|Replay the same request three times before changing any input.|The response body is stable except for a timestamp and request ID.|Establish normal noise first. Record status, length, key text, cookies, redirects, and timing. A response diff is meaningful only against this baseline.|One slow request does not prove a time-based vulnerability.|How many matching true/false pairs would make your timing hypothesis more convincing?`,
`Make falsifiable hypotheses|Hypothesis: the account ID is trusted. Change only account=alice to account=bob.|The response now contains Bob's email while the session remains Alice's.|A hypothesis predicts an observable result. Use a control account and one changed variable so you can explain which boundary failed.|A 200 response with Alice's own data falsifies this particular object-reference test.|What additional evidence would separate a public profile from private account data?`,
`Observe redirects and errors|Disable automatic redirect following for a request returning 302.|The redirect body unexpectedly contains a private record before the login page loads.|Inspect the complete response, not just the final browser view. A redirect does not retract bytes already sent.|A stack trace alone does not prove code execution; it identifies components and inputs.|What can the Location header, cookies, and intermediate body tell you separately?`,
`Keep an evidence notebook|Record a baseline request, one mutation, response diff, and alternative explanation.|You can reproduce the finding after logging in again.|Reproducibility keeps guesses from becoming conclusions. Include the role, state, decoding steps, and an unsuccessful control.|A saved payload without its endpoint, session state, and expected result is hard to reuse.|What would another solver need to reproduce the smallest proof?`],
'information-disclosure': [`Information disclosure`,`An error message can be a receipt with the shop's filing cabinet address printed on it. The address is a clue; it is not automatically the prize.`,
`Errors reveal architecture|Replace a numeric product ID with a nonnumeric marker.|A stack trace names a template path and database driver.|Unexpected types can expose internal implementation details. Turn those details into specific hypotheses about parsers, versions, and file locations.|A version banner may be stale or backported; verify behavior before choosing an exploit.|Which part of the error reveals a new input or trust boundary?`,
`Debug pages and backup files|Compare /debug, an observed source filename, and that filename with a backup suffix.|A backup download reveals source containing a hardcoded configuration value.|Debug endpoints and forgotten artifacts can bypass the application view layer. Inspect source references rather than blindly guessing thousands of files.|A missing .bak file does not rule out version-control history, editor backups, or build artifacts.|If a source comment names another file, what minimal request tests that lead?`,
`Version-control history|Compare the current configuration with an earlier committed version.|A removed credential remains in an old revision.|Deleting a secret from the latest file does not remove it from history. Exposed repository objects can preserve past content.|Finding a repository directory does not ensure its objects are downloadable or complete.|What evidence distinguishes a fake directory listing from a recoverable repository?`,
`Trust in internal headers|Add an observed internal identity header to a normal unauthenticated request.|The model's backend accepts a header the edge should have replaced.|Disclosure may reveal how the proxy represents client identity. The flaw is trusting caller-controlled metadata, not merely printing its name.|Spoofing an arbitrary header has no effect if the edge strips it or the backend ignores it.|How would you test whether the edge overwrites your supplied identity header?`],
'path-traversal': [`Path traversal`,`A file service should fetch books from one shelf. Traversal persuades it to walk out of that shelf before choosing the book.`,
`Relative and absolute paths|Compare image=cat.png, image=../notes.txt, and image=/srv/notes.txt.|The relative path escapes the images folder; an absolute path bypasses prefix joining in this model.|The important boundary is the canonical resolved path staying within the allowed root. Libraries differ on how absolute paths override a base.|A failed ../ probe may reflect filtering, a wrong depth, or an incorrect target path.|How would you test absolute-path handling without assuming a specific operating system?`,
`Non-recursive stripping|Change ../notes.txt to ....//notes.txt against a filter that removes ../ once.|One replacement leaves ../notes.txt for the file loader.|Removing a forbidden substring can create a new forbidden substring. Canonicalize and validate instead of repeatedly patching strings.|This works only for that replacement behavior; recursive removal or a proper root check blocks it.|What string will remain after the exact filter runs once?`,
`Decode after validation|Compare %2e%2e%2fnotes.txt with %252e%252e%252fnotes.txt.|A second decoder turns the latter into traversal after the first filter has run.|Trace each transformation in order. A payload must arrive at the file operation as path syntax, even if it looked harmless to an earlier check.|If the server performs one decode only, the double-encoded string remains a literal filename.|Which component performs the final decoding step?`,
`Prefix and extension checks|Test /srv/images/../notes.txt and a legacy filename ending in %00.png.|The prefix-only model escapes its root; a legacy null-terminated loader ignores the suffix.|A textual prefix is not containment. Null-byte truncation requires a vulnerable runtime or native boundary and does not apply to most modern file APIs.|Do not infer null-byte support merely because an old walkthrough uses it.|What resolved path should a robust allow-root check compare?`],
'access-control': [`Access control`,`Knowing a hotel room number is different from being allowed inside it. Every door needs its own permission check, even if the lift hides the floor.`,
`Objects and ownership|Keep Alice's session and change invoice=41 to invoice=42.|The model returns Bob's invoice because it checks login but not ownership.|Horizontal access control separates users with the same role. Random IDs reduce guessing but do not replace permission checks.|A public record is not proof of unauthorized private access; compare two controlled accounts.|Does the endpoint authorize the object against the authenticated account?`,
`Roles and client fields|Add role=admin to a profile update, then request the admin action.|The stored role changes because an unrestricted update accepts a privileged field.|Vertical escalation crosses role boundaries. Hidden buttons, request cookies, and editable profile fields must not define trusted permissions.|Changing a role cookie fails when the real role is loaded from the server session.|Which value is persisted, and which value is used at the sensitive action?`,
`Methods and rewritten URLs|Compare a protected POST with an alternative method or an edge-supported rewrite header.|The route reaches the same action through a path missing the original permission check.|Authorization must apply consistently across methods, routing aliases, and proxy rewrites. A front-end deny rule cannot protect an unchecked backend route alone.|An unsupported method returning 405 gives no evidence of bypass.|Do the proxy and application agree on which action this request invokes?`,
`Multi-step and redirect leaks|Skip the approval page and send the final confirmation directly.|The last step executes without checking the current account's role.|Every sensitive step must validate permissions and state. A redirect can also leak a private response body before the browser follows it.|Successfully loading a form is weaker evidence than successfully performing the restricted action.|Where does the server actually commit the protected change?`],
authentication: [`Authentication`,`A login desk checks who you are; access control decides where you may go. Weak recovery or a half-finished identity check can make the front desk irrelevant.`,
`Username enumeration|Compare invalid-user and valid-user login attempts with the same wrong password.|One response differs subtly in wording; repeated controls rule out random noise.|Status, message, timing, and account-lock behavior can reveal whether an account exists. Normalize variable fields before comparing.|One long response can be network jitter or password-hash cost unrelated to username validity.|Which stable signal survives repeated matched requests?`,
`Rate limits and batches|Compare five guesses as five requests with five credentials in one JSON array.|The model counts requests rather than individual attempts, so a batch exceeds the intended budget.|Identify the rate-limit key: account, IP, session, endpoint, or request. Success resets and parallel execution may change the counter.|Sending X-Forwarded-For helps only when a trusted component mistakenly uses that caller value.|What event increments or resets the actual attempt counter?`,
`Multi-factor state|After passing the password step, request /account before submitting the second factor.|A flawed endpoint treats a provisional session as fully authenticated.|Multi-factor authentication requires a distinct server-side state and account binding at every post-login action. A second-factor code must belong to that login attempt.|A displayed verification page does not prove the protected endpoints enforce verification.|Can a code issued for one account complete another account's pending login?`,
`Recovery and password change|Submit a password-reset token for Alice with username changed to Bob.|The model updates Bob because token ownership is never compared to the selected account.|Bind reset tokens to account, purpose, expiration, and one-time use. Password-change endpoints have their own enumeration and brute-force risks.|A reset link arriving by email proves delivery, not correct token binding.|Which server-side lookup determines the account whose password changes?`,
`Persistent cookies and offline guesses|Decode a remember-me token containing a username and password-derived hash.|Guess validation can happen locally once the format and hash are known.|Encoding is not protection. Weak password-derived tokens can enable offline guesses without rate limits; signatures with strong independent keys prevent tampering.|A secure random opaque token cannot be cracked as if it were a password hash.|What evidence establishes the token's construction rather than merely its appearance?`],
'business-logic': [`Business logic`,`A cashier may scan every item correctly but still accept a negative number of items. Logic bugs exploit the rules between valid operations.`,
`Prices, quantities, and arithmetic|Change quantity=1 to quantity=-1 in a signed-in checkout.|The model subtracts a negative price and increases the balance.|Server calculations must enforce domain constraints, not just numeric types. Overflow, huge values, rounding, and currencies can break assumptions too.|A negative value rejected at this endpoint may be accepted by an earlier cart endpoint.|Where are totals recalculated, and what numeric range is valid?`,
`Workflow and identity state|Open a dual-use registration endpoint while already signed in.|An existing session is modified using assumptions intended only for a new account.|Map state transitions and identity sources across signup, login, checkout, and recovery. Endpoints shared across workflows can inherit incompatible assumptions.|Skipping one UI page is harmless when the server validates all transition prerequisites.|Which step establishes identity and which later step merely assumes it?`,
`Coupons and infinite-value loops|Apply two permitted promotions in alternating order, then refund the result.|The model refunds full face value after a discounted purchase.|A business invariant must hold across a sequence, not just one request. Repeatability distinguishes a one-time discount from an unbounded value loop.|A single unexpected total may be intentional; calculate net value over a complete cycle.|Does returning to the starting state leave you with more credit than before?`,
`Parsing and exceptional inputs|Compare an email address as shown by the account UI with the domain extracted by the privilege checker.|The two parsers disagree about which domain owns the address.|Length truncation, unusual syntax, case handling, and parser differences can violate identity rules. Compare the stored, displayed, delivered, and checked values.|A strange accepted email is not escalation unless a security decision uses a different interpretation.|Which two components assign different meanings to the same input?`,
`Encryption oracles|Submit a controlled value to an encryption feature, then reuse the resulting ciphertext in an identity feature.|The model accepts ciphertext minted for a different purpose.|Confidentiality alone does not establish token purpose. Shared unauthenticated formats can let one feature mint credentials for another.|Randomly editing modern authenticated ciphertext normally fails integrity validation.|Are purpose and identity bound inside an authenticated token?`],
'sql-injection': [`SQL injection`,`A database query is an instruction with spaces reserved for values. Injection happens when a value is allowed to rewrite the instruction itself.`,
`Break the data boundary|Compare category=Books with category=Books' OR '1'='1'-- .|The concatenated WHERE condition becomes true for rows outside Books.|A quote can end a string literal. Boolean operators alter query logic; comment syntax depends on the database. Parameters keep input as data.|An unmatched quote may only cause an error; it does not establish a working data-extraction channel.|Which part of the query is controlled and which result change would confirm it?`,
`UNION shape and types|Compare a two-column original query with UNION SELECT NULL,NULL and then UNION SELECT 'marker',NULL.|Two columns fit; the text marker reveals which displayed column accepts text.|UNION combines compatible result sets. Determine column count, compatible types, and rendered positions before retrieving values. Concatenate fields when only one position is visible.|A type error can mean the count is correct but a selected column has an incompatible type.|How would you separate a wrong column count from a wrong data type?`,
`Fingerprint and enumerate|Compare an Oracle version query through v$version with a MySQL version() expression.|Only the query matching the model's dialect succeeds.|Database functions, comments, concatenation, catalog tables, and Oracle's DUAL conventions vary. Identify the dialect, then enumerate tables and columns instead of guessing them.|A function failing can reflect permissions or query context, not necessarily the wrong database.|What minimal version or catalog query fits the confirmed output shape?`,
`Blind boolean and error channels|Alternate a known true and known false condition in a tracking cookie.|The greeting toggles even though no query results are printed.|A blind channel leaks a bit through content, conditional errors, or type-conversion errors. Recover length first, then test characters or ordered ranges with repeated controls.|An application-wide error independent of the condition cannot reveal a bit.|What paired conditions establish that the observed signal depends on your predicate?`,
`Timing and out-of-band channels|Compare a delay conditioned on true with the same delay conditioned on false.|Only true is consistently slower across repeated pairs.|Timing needs a supported delay primitive and statistical controls. Out-of-band callbacks use a separate observable network channel; permissions and egress decide availability.|A single timeout can be load or blocking. An absent callback can mean egress restrictions rather than no injection.|When content is identical, which independent signal can carry your next bit?`,
`Encoding and second-order input|Submit an encoded quote in XML that is decoded before a concatenated query.|The filter sees an entity while the database receives query syntax.|Map transformations to the final sink. Stored input can become dangerous only on a later query; this is second-order injection. A web filter cannot replace parameterization.|Encoding is useful only if the target actually decodes it before the vulnerable sink.|At which stage does a harmless representation become active SQL syntax?`],
'nosql-injection': [`NoSQL injection`,`A query document is a set of search instructions. Giving someone a whole document when you expected one name lets them smuggle in extra search rules.`,
`Syntax versus operators|Compare a string username with {"username":{"$ne":"nobody"}}.|The model accepts an operator object instead of a literal username.|NoSQL injection can alter query syntax or inject operators through structured input. Preserve types while tracing how JSON becomes a query document.|A SQL quote payload may be meaningless when the application expects a MongoDB operator object.|Does the request parser preserve an object, stringify it, or reject it?`,
`Authentication query logic|Keep a valid username and replace only its password value with a matching operator.|The query finds a user without comparing a literal supplied password.|Operator injection changes matching behavior. A real application should validate the input schema and compare a password hash separately.|An empty result may mean the username was also changed or the chosen operator is filtered.|Which minimal field change proves that password comparison was bypassed?`,
`Blind field extraction|Compare a true and false character predicate in a server-evaluated query expression.|The response toggles according to a stored field's tested character.|A syntax-injection channel can infer field length and characters. The exact expression depends on whether JavaScript evaluation is enabled.|Modern configurations may disable server-side JavaScript; operator injection can exist without it.|What non-destructive true/false predicate confirms the available evaluation context?`,
`Discover unknown keys|Test whether a candidate reset-token field exists before testing its value.|The existence predicate changes the modeled result.|Unknown fields require schema discovery rather than assuming names. Use controlled predicates and distinguish missing, null, empty, and false values.|A falsy result does not always mean the field is absent.|How would you distinguish an absent field from a present field holding an empty string?`],
'command-injection': [`OS command injection`,`A program should hand a delivery driver an address as data. Passing that address through a shell lets punctuation become another instruction to the driver.`,
`Shell boundaries|Compare a plain stock ID with 7; printf marker in a shell-built command.|The extra command contributes marker to the output.|Shell metacharacters can separate commands when input reaches an interpreter. Prefer fixed executable arguments without a shell; quoting rules vary across platforms.|A semicolon remains ordinary data in an argument-array process call.|Does the program invoke a shell, and which operating-system syntax applies?`,
`Blind timing|Compare a short conditionally triggered delay with an otherwise matching control.|Only the modeled injected command delays the response.|A hidden command's output may not be returned. Repeated timing pairs can establish execution, but are weaker than a unique independent marker.|A timeout alone could be a network failure or an expensive application action.|What repeatable control distinguishes command execution from ordinary slowness?`,
`Output redirection|Direct a harmless marker into a known lab-writable web directory, then fetch it.|The marker is available through a second request.|A write-and-read channel can expose otherwise hidden command output. It requires filesystem permissions, a predictable location, and a reachable read route.|A missing file may reflect permission or serving-path differences, not a safe command builder.|Which evidence connects the written file to this specific execution attempt?`,
`Out-of-band confirmation|Use a unique callback identifier in a lab command and check the callback service.|The callback correlates with that one request.|An external interaction can establish a separate execution channel. DNS and HTTP egress differ; encoded output may require chunking and correlation.|A callback can also come from a URL fetcher; its context must establish command execution.|What callback content would distinguish a shell from a generic network client?`],
ssrf: [`Server-side request forgery`,`A server can be a courier with access to rooms you cannot enter. SSRF makes that courier fetch your chosen address using its own network position.`,
`Localhost and internal services|Change a stock-check URL from a supplier to http://127.0.0.1:8080/status.|The response comes from the server's internal service.|The server's localhost is different from your browser's localhost. Internal trust, credentials, and network access can make a fetch security-sensitive.|A generic fetch error does not reveal whether routing, DNS, scheme, port, or permissions caused failure.|Which part of the response proves which service answered?`,
`Blacklist and allowlist parsing|Compare a permitted hostname with a URL containing userinfo before @.|A naive substring check approves a URL whose parsed hostname is different.|Validate the parsed scheme, host, resolved addresses, and redirects with consistent URL rules. Alternative IP forms and DNS resolution can defeat textual checks.|A bypass from one URL library may fail in another; inspect the actual destination rather than memorizing syntax.|What hostname does the fetcher parse after userinfo is removed?`,
`Redirect chains|Submit an allowed URL that responds with a redirect to an internal address.|The model follows the redirect without rechecking the destination.|Every hop needs the same destination policy. An open redirect can bridge an otherwise valid initial-host check.|A fetcher that disables redirects or validates each hop blocks this route.|Does validation apply to the first URL only or to every resulting connection?`,
`Blind SSRF and secondary impact|Trigger a unique callback URL where the page never prints the fetched body.|A callback arrives despite the unchanged page.|Blind SSRF is a network observation, not automatically file read or code execution. Some chains require a vulnerable internal service, such as a CGI environment affected by Shellshock.|A DNS lookup alone does not prove that an HTTP request completed or an internal action succeeded.|What is proven by DNS evidence, and what further evidence would prove the next step?`],
xxe: [`XML external entities`,`An XML document can include a note saying “insert the contents from this address.” An unsafe parser follows the note with the server's file and network access.`,
`External entity expansion|Add an external entity declaration and reference that entity in a displayed XML field.|The modeled parser inserts local file content into the stock response.|A document type definition can declare entities. Expansion is dangerous when external resources are enabled; parser configuration controls the behavior.|Rejecting a DOCTYPE prevents this route but does not rule out XInclude or another XML parser elsewhere.|Which displayed field proves that the external entity was expanded?`,
`SSRF through XML|Change the entity's system identifier from a file URL to an internal HTTP URL.|The parser requests the internal resource instead.|XXE is an XML-parser entry point; SSRF is the resulting server-side request capability. Distinguish entry mechanism from impact.|An HTTP entity may be blocked while local files remain readable, or vice versa.|Which URI schemes and network paths does this parser support?`,
`Blind entities and external DTDs|Reference a lab-controlled external DTD with a unique callback identifier.|A callback reveals entity processing without visible XML output.|Parameter entities operate inside DTD processing. External DTD techniques depend on parser rules; separate fetching a DTD from successfully expanding its contents.|Fetching an external DTD does not automatically mean local file bytes can be exfiltrated.|What second observation proves data expansion rather than only DTD retrieval?`,
`Errors and local DTD reuse|Use a parser error that includes an expanded value, or override an entity in an available local DTD.|The error becomes the output channel when outbound traffic is blocked.|Error-based extraction and local-DTD repurposing need parser-specific behavior and readable target resources. Establish those prerequisites before chaining them.|An uninformative error or unavailable DTD blocks that specific channel.|What local resource and error behavior must be demonstrated first?`,
`Hidden XML and XInclude|Compare a normal text field with an XInclude element in server-generated XML; inspect an SVG upload separately.|The inclusion-aware model reads a referenced text resource without a supplied DOCTYPE.|XML can appear behind JSON conversions, document imports, and SVG images. XInclude is a separate feature from entity expansion.|Disabling external entities does not by itself configure XInclude safely.|Which transformation sends your otherwise ordinary input into an XML processor?`],
ssti: [`Server-side template injection`,`A template is a stencil with blank spaces for names. The dangerous mistake is letting a name redraw the stencil before printing.`,
`Data versus template source|Compare a literal name with a candidate expression such as {{7*7}}.|The template-source model prints 49; the data-only model prints the literal braces.|Server-side template injection requires input to become template source. Arithmetic is a useful probe, but one matching result is not enough to identify an engine.|Client-side rendering or application arithmetic can imitate this result.|Does the raw server response contain the evaluated result before browser scripts run?`,
`Identify engine and context|Compare expression syntax and error details across two candidate template engines.|Only syntax supported by the modeled engine evaluates.|Text context differs from an existing expression or statement context. Use documentation and minimal discriminating probes to identify grammar before exploring objects.|An expression failing can mean the wrong context rather than the wrong engine.|Which surrounding delimiter must be completed before a new expression can execute?`,
`Inspect exposed objects|Read a harmless attribute from an object intentionally exposed to the template.|The output reveals the object's type and available application data.|Template context objects can expose secrets or capabilities. Follow documented attributes and permissions rather than assuming a universal object chain.|A readable property does not imply arbitrary method calls or process execution.|Which exposed object crosses from presentation into filesystem, configuration, or application logic?`,
`Sandbox and custom chains|Compare access to a permitted display method with a restricted object capability.|The model blocks one method but exposes another path to the same sensitive operation.|A template sandbox limits capabilities; bypasses are engine- and version-specific. A custom exploit requires tracing reachable objects and effects, not copying a canned chain.|A published chain for another engine version may be irrelevant.|What concrete capability is reachable in this engine and how would you prove it minimally?`],
xss: [`Cross-site scripting`,`A page is a stage script with blanks for visitor comments. XSS happens when a comment becomes stage directions executed in another visitor's browser.`,
`Reflection, storage, and DOM sinks|Trace a marker in the raw response, a later visitor's page, and a JavaScript DOM update.|Each route can reach an HTML-parsing sink, but at a different point.|Reflected input returns immediately; stored input persists; DOM input is processed by browser code. A source supplies data and a sink interprets it.|Reflection alone is not execution. innerHTML and document.write have different script execution behavior.|Which parser and sink will process the marker in the victim's browser?`,
`HTML and attribute contexts|Place a quote in <input value="MARKER"> while angle brackets are encoded.|The quote can end the attribute even when new tag syntax is unavailable.|Identify whether input sits in text, a quoted attribute, a URL, or executable content. Each requires a different boundary crossing and compatible event trigger.|An HTML-text payload cannot work unchanged inside every attribute or select element.|What character closes the current context, and what syntax becomes legal afterward?`,
`JavaScript strings and literals|Compare a single quote inside a JavaScript string with </script> inside an inline script block.|The HTML parser can terminate the script block before JavaScript string rules apply.|Inline script has nested HTML and JavaScript parsers. Backslash handling, template literals, Unicode escapes, and event attributes change the escape sequence.|Escaping one quote does not cover backticks, expression interpolation, or the enclosing HTML parser.|Which parser gets the first chance to interpret your next characters?`,
`URLs and framework expressions|Compare an ordinary https: link with a javascript: link and an AngularJS-style expression.|URL navigation and expression evaluation use different execution rules.|URL schemes require validation, not just HTML escaping. Framework expression contexts add their own grammar and version-specific sandbox behavior.|Quote encoding can protect an attribute boundary while leaving a dangerous URL scheme intact.|Does the dangerous value execute as a URL, a framework expression, or HTML?`,
`Filter constraints and event triggers|Test which tags, attributes, and events survive a model allowlist before choosing a candidate.|A surviving SVG element behaves differently from a custom HTML element.|Build a constraint inventory: allowed syntax, required user interaction, browser behavior, and execution sink. A payload must satisfy all four.|A tag surviving filtering is not proof its event fires or its handler survives.|Which observation proves actual execution rather than mere markup insertion?`,
`Impact and browser defenses|Compare script reading document.cookie with script making a same-origin authenticated request.|HttpOnly hides a cookie but does not stop the browser attaching it to same-origin requests.|Script execution in the victim origin can act with that session. Cookie theft, credential capture, and CSRF-token access are distinct impacts with distinct prerequisites.|HttpOnly reduces cookie exposure; it does not fix XSS. Some actions still require extra confirmation.|What action can the current victim session perform without reading its cookie?`,
`CSP and markup-only channels|Compare an inline script blocked by Content Security Policy with an allowed resource load containing injected markup.|The policy blocks one execution route while a separate markup leak may remain.|CSP restricts sources and script execution; nonces, allowed hosts, script gadgets, and dangling markup need separate analysis. A policy bypass depends on its exact directives.|A nonce in the page cannot simply be guessed; a CSP error does not prove all possible impact is gone.|Which directive blocks your attempt, and what permitted capability remains?`],
dom: [`DOM-based vulnerabilities`,`Browser code moves messages between compartments. A safe-looking input becomes dangerous if it reaches a compartment that treats data as instructions.`,
`Trace sources to sinks|Follow location.search into a DOM insertion and location.hash into a navigation assignment.|The first route parses HTML; the second can redirect the browser.|Track sources such as URLs, storage, and messages through transformations to sinks. An HTML sink and a navigation sink need different proofs and defenses.|A source appearing in JavaScript is not a flaw until it reaches a dangerous operation.|What exact function interprets the value, and in which grammar?`,
`Web messages and origins|Send a structured message from another origin to a listener lacking an origin check.|The model accepts the message and updates the page.|postMessage receivers must validate sender origin, expected window, and message structure. JSON.parse parses data; it does not make later HTML or URL use safe.|A substring check on event.origin can trust an unrelated host containing that substring.|What exact origin and message schema should the receiver accept?`,
`Open redirects and cookies|Change a return URL and then a client-side cookie value sourced from the query string.|The browser changes destination or stores attacker-selected state.|Client-side redirects can support phishing or token leaks. Cookie manipulation matters when later code or the server trusts the chosen value.|Writing a cookie alone does not prove you can overwrite an HttpOnly or differently scoped cookie.|Which later security decision consumes the manipulated value?`,
`DOM clobbering|Insert named form elements matching a variable that code assumes is a configuration object.|A named DOM property shadows the expected configuration value.|HTML elements can be exposed through named properties. Type confusion between elements, collections, and plain objects can steer unsafe sinks.|A matching id is insufficient if code uses explicit local variables and type checks.|Which property lookup changes type after the markup is inserted?`],
csrf: [`Cross-site request forgery`,`A browser is a courier that automatically carries your membership card. CSRF sends that courier to perform an action you never chose.`,
`Ambient credentials and actions|Submit a cross-origin form to a model email-change endpoint with no token.|The session cookie accompanies a request that changes the account.|CSRF needs an action, automatically attached credentials, and a request an attacker can cause. Reading the response is not required.|CORS blocking response reads does not stop all cross-origin form submissions.|Can the action be triggered with browser-sendable headers, method, and body?`,
`Token presence, method, and binding|Compare a missing token, an attacker-session token, and a changed method.|The flawed model validates POST tokens only when the field is present.|Tokens must be required, unpredictable, and bound appropriately to the authenticated session. Test omission, empty values, reuse, and cross-account substitution separately.|A hidden token is not a defense if the server accepts omission or another user's token.|Which single negative control should a correctly implemented endpoint reject?`,
`Double-submit and cookie binding|Provide a matching token in both a writable cookie and request field.|A naive equality check accepts attacker-selected matching values.|Double-submit designs need integrity and appropriate session binding. Cookie injection through another weakness can defeat a bare equality scheme.|A token copied from a different session fails when the server cryptographically binds it.|What ability is required to choose the victim's cookie value?`,
`SameSite and navigation|Compare a cross-site POST with a top-level GET using a method override.|The Lax model with a state-changing GET accepts a navigation that a POST form would not.|SameSite depends on site, navigation, method, browser behavior, and cookie configuration. Same-site sibling origins and client-side redirect gadgets need separate analysis.|A SameSite=Strict cookie is not automatically protected from an attacker operating on a same-site sibling.|Is this request cross-origin, cross-site, top-level, and safe-method?`,
`Referer and Origin checks|Remove Referer, then use a URL containing the trusted hostname only in an unrelated location.|A presence-optional or substring validator accepts the crafted case.|Validate parsed origins exactly and define behavior for absent headers. Referer may be suppressed; Origin and token defenses should not rely on arbitrary substring matching.|A browser cannot freely set every header as a script chooses; prove a deliverable browser request.|Which crafted request can a real attacker-controlled page actually send?`],
cors: [`Cross-origin resource sharing`,`A browser can deliver letters between buildings but usually refuses to let one building open another's mail. CORS is the recipient's instruction about who may read the reply.`,
`Reflected origins and credentials|Send Origin: https://other.example.test to a credentialed private-data endpoint.|The model reflects the origin and sets Access-Control-Allow-Credentials: true.|A browser may expose the response if the allowed origin exactly matches the requesting origin and credential conditions hold. Arbitrary origin reflection can grant unintended reads.|A wildcard allowed origin does not allow credentialed reads in the same way; verify actual browser behavior.|Will the browser attach credentials and expose this response to that specific origin?`,
`Null origins|Compare an absent Origin header with Origin: null from a sandboxed document.|Only the explicitly trusted null origin is allowed by the model.|Some sandboxed, file, or opaque-origin documents serialize their origin as null. Trusting null admits unrelated documents sharing that representation.|The literal string null is not equivalent to no Origin header.|What browser context can generate a real opaque-origin request?`,
`Trusting insecure siblings|Allow an HTTP sibling origin to read an HTTPS account response.|The policy extends trust to a less-protected origin.|CORS trust is only as strong as the allowed origins. A vulnerable or insecure trusted sibling may become a bridge to sensitive data.|A trusted origin alone is not an exploit without control or script execution there and credential delivery.|Which extra foothold turns this CORS rule into a usable cross-origin read?`],
clickjacking: [`Clickjacking`,`A transparent sheet can place a real button under a misleading label. The victim clicks the genuine site, but chooses an action they did not intend.`,
`Frames and genuine clicks|Overlay a transparent framed account page beneath a harmless-looking button.|The modeled click lands on the real account action with valid session and tokens.|Clickjacking abuses UI intent. CSRF tokens can be valid because the action occurs inside the real page. Frame restrictions such as frame-ancestors address embedding.|A site that refuses framing blocks this path even if its form has no extra confirmation.|Can the target page be framed and authenticated in the victim's browser?`,
`Prefilled fields and frame busters|Load a target form with URL-prefilled data and a JavaScript frame-busting check.|A script-only defense is weaker than an enforced framing policy.|URL parameters can reduce needed interaction. Frame-buster behavior depends on sandbox and navigation rules; test the real browser delivery path.|A screenshot of alignment does not prove a click reaches an enabled target.|Which form values and click positions remain stable across viewport changes?`,
`Multi-step and DOM chains|Align two consecutive confirmation controls, then compare a page whose click runs a DOM sink.|The second click completes a workflow or triggers a separate DOM bug.|Multi-step clickjacking requires tracking UI state. A clickjacking-to-XSS chain adds another vulnerability and its own trigger conditions.|One aligned button does not establish that subsequent dialogs can be controlled.|What must stay predictable after the first user interaction?`],
websockets: [`WebSockets`,`A WebSocket is a conversation kept open after the initial introduction. Checking the introduction does not make every later sentence trustworthy.`,
`Handshake and message validation|Connect normally, then change a JSON chat message field.|The model processes the changed message without a new HTTP request.|The HTTP upgrade establishes a channel; individual messages still require input validation and authorization. Inspect both handshake and frames in a proxy.|An HTTP-only scanner may miss vulnerabilities that exist only in frames.|Which message action uses a server-side identifier or dangerous rendering sink?`,
`Handshake metadata and identity|Change a caller-controlled handshake header used for an IP-based block.|The model assigns a different identity to the same client.|Headers used during upgrade can affect session or anti-abuse logic. Preserve the distinction between trusted proxy metadata and raw client headers.|A spoofed header is harmless when the edge strips it before the application reads it.|Does changing the header change an actual security decision?`,
`Cross-site WebSocket hijacking|Open a socket from a different origin where the handshake trusts only cookies.|The model streams private messages to the other origin.|A cookie-authenticated handshake needs origin and anti-CSRF consideration. WebSocket origin checks are separate from ordinary CORS response rules; cookie policies still matter.|A successful unauthenticated upgrade does not prove access to an authenticated stream.|Which handshake and cookie conditions allow the victim's session to be reused?`],
'api-testing': [`API testing`,`An API is a service counter whose order form is a request. The printed form rarely lists every instruction the counter will accept.`,
`Discover endpoints and methods|Compare observed /api/v1/items/7 with a documented alternative method on the same resource.|The model reveals a write operation absent from the UI.|Inventory paths, versions, methods, schemas, content types, and authentication. Documentation and client scripts provide leads; each lead still needs a verified response.|A 404 can conceal an authentication requirement or a wrong version, not necessarily a missing resource.|Which observed naming pattern suggests the smallest next endpoint test?`,
`Mass assignment|Add a privileged field to an otherwise valid JSON profile update.|The model stores a field the UI never offered.|Automatic object binding can accept unintended fields. Compare response objects, documentation, and update schemas; sensitive fields need explicit allowlists and authorization.|A reflected field may be ignored rather than persisted; fetch the object again.|Does the added field change a stored value or a privileged behavior?`,
`Server-side query pollution|Send an encoded separator inside a parameter forwarded to an internal query string.|The downstream parser treats the decoded separator as another parameter.|An outer request value becomes syntax in an inner request. Track decoding, separators, duplicate handling, and which downstream fields are security-sensitive.|A separator may remain encoded all the way downstream; a different error alone is not proof.|What does the exact inner request look like after all transformations?`,
`REST path pollution|Insert an encoded path delimiter into an identifier used to build an internal API path.|The model resolves a different internal endpoint than the front end validated.|Path normalization and URL construction can change a resource identifier into routing syntax. Fixing only query-string handling leaves path construction exposed.|A normalized path can still be rejected by the downstream service's own authorization.|Which endpoint receives the final internal request and under whose credentials?`],
graphql: [`GraphQL`,`A GraphQL endpoint is a custom order desk where you specify exactly which fields to receive. Permission must be checked for every dish, not just at the counter.`,
`Schema and hidden fields|Request an observed object with a private-looking field and compare schema discovery responses.|The model resolves a field omitted by the UI.|A schema defines types and fields; introspection may reveal it. Hidden UI fields and disabled introspection do not replace field-level authorization.|An error suggesting a field name is a discovery clue, not proof its data is readable.|Which resolver checks the requesting user's right to this object and field?`,
`Find endpoint and transport|Compare a conventional query on likely observed endpoint paths and allowed content types.|One route returns a GraphQL-shaped error instead of generic HTML.|Use client references and response structure to identify GraphQL. Introspection restrictions can depend on parsing and request format.|A URL named /graphql does not guarantee GraphQL, and a hidden route can still enforce authorization correctly.|What minimal query proves a real GraphQL parser is answering?`,
`Aliases and rate limits|Submit several differently aliased login fields in one GraphQL operation.|The model executes multiple resolver calls but increments a request counter once.|GraphQL aliases give distinct result names to repeated fields. Limits must consider operation cost and sensitive resolver invocations, not only HTTP requests.|An implementation may disable batching or enforce resolver-level limits.|How many authentication attempts occur inside one accepted HTTP request?`,
`GraphQL and CSRF|Replay a mutation using a browser-sendable form content type accepted by the endpoint.|The model performs the mutation with the victim's cookies.|GraphQL is not inherently CSRF-resistant. Accepted methods, content types, cookie behavior, and tokens determine whether a cross-origin page can trigger a mutation.|A JSON-only endpoint requiring custom headers may trigger preflight, changing exploitability.|Can the mutation be delivered as a real browser request without prohibited headers?`],
oauth: [`OAuth & OpenID Connect`,`OAuth is a valet ticket granting specific access, not a password for every service. Trouble starts when tickets, recipients, and the person collecting them are not bound together.`,
`Code flow and identity binding|Compare a provider-authenticated identity with an email field supplied by the browser during implicit-flow login.|The model signs in as the supplied email without verifying it against the provider.|OAuth delegates access. OpenID Connect adds identity claims. The relying party must bind authenticated claims, intended audience, and its login session.|Receiving a genuine access token does not authenticate every email supplied alongside it.|Which identity is verified by the provider, and which identity is merely a request field?`,
`State and account linking|Initiate linking under one account, then complete the callback in another session without a bound state value.|The model links the provider account to the wrong local account.|State protects request correlation when correctly unpredictable and session-bound. Linking needs explicit user intent and identity checks in addition to callback validity.|A state value existing in the URL proves nothing about server-side validation.|What session initiated this link, and what session is allowed to finish it?`,
`Redirect validation and token leaks|Compare an exact registered callback with an accepted prefix leading to an open redirect.|The token or authorization response reaches an unintended destination.|Validate redirect destinations precisely. Code flow, implicit fragments, referrers, proxy pages, and browser navigation have different leakage paths; PKCE binds intercepted codes to a verifier.|An open redirect does not automatically leak a fragment or usable code; follow the actual browser and token flow.|At which hop do credentials become visible to an attacker-controlled origin?`,
`Dynamic registration and fetches|Submit an external metadata URL through OpenID client registration.|The model fetches metadata server-side and reaches a lab callback.|Discovery and dynamic registration can add SSRF surfaces through remote metadata and key URLs. Validate fetch destinations and bind client metadata to trust policy.|Registration being available is not a vulnerability by itself.|Which registration field causes a network request, and is its destination constrained?`],
jwt: [`JSON Web Tokens`,`A signed token is a readable badge with a tamper-evident seal. Reading the badge is easy; accepting a badge without checking who made the seal is the mistake.`,
`Decode, edit, and verify|Change the role claim while keeping the original signature.|The secure model rejects the token; an unverified-decoding model accepts it.|A JWT normally contains base64url header, payload, and signature. Verification must precede trust in claims and enforce expiration, issuer, and audience.|Decoding a token does not mean its signature can be forged.|What specific evidence shows the application accepted a modified signed claim?`,
`Algorithms and weak secrets|Compare a token declaring no signature with a correctly signed token using a weak HMAC secret.|The flawed model accepts an allowed-by-client algorithm or a guessed secret.|The verifier chooses an allowed algorithm from trusted configuration. HMAC secrets must be strong; offline guessing requires a known signed token and candidate verification.|A dictionary miss does not prove the secret is strong, and alg=none is usually rejected.|Which cryptographic operation does the server actually perform for this algorithm?`,
`Attacker-chosen keys|Add a jwk header or jku URL pointing to a key you control.|The model verifies your signature with your own supplied key.|An embedded key or remote key-set URL is not a trust anchor. Keys must come from trusted issuer configuration and constrained retrieval.|A matching kid only selects among keys the verifier is willing to trust; it should not establish trust itself.|Who controls the key used for verification and how is its issuer authenticated?`,
`Key identifiers and paths|Change kid to a path-like value in a verifier that loads keys from filenames.|The model reads a different verification-key source.|A key identifier should be an opaque selector from a fixed trusted set. Path traversal or query injection in key lookup creates a separate vulnerability.|A traversal string is ineffective when kid is mapped through a fixed in-memory dictionary.|Which lookup operation consumes kid before verification happens?`,
`Algorithm confusion|Present an HS256 token to a verifier that incorrectly reuses RSA public-key bytes as an HMAC secret.|The model accepts a MAC created with publicly available bytes.|Confusing asymmetric and symmetric verification can turn a public key into a forgeable shared secret. Exact key serialization and verifier behavior matter.|Modern libraries often reject this configuration. An absent public key adds a separate key-recovery prerequisite.|Why are public RSA verification bytes unsuitable as an HMAC secret?`],
'file-upload': [`File upload vulnerabilities`,`A receiving desk should store a parcel, not execute the note inside it. File uploads become dangerous when storage, validation, and interpretation disagree.`,
`Storage versus execution|Upload a harmless text marker with a server-executable extension to a modeled executable directory.|Retrieving the file runs the server interpreter instead of serving plain bytes.|Upload impact depends on destination, permissions, handler configuration, and retrieval. A public URL alone does not imply server-side code execution.|Renaming an image to a script extension does nothing when the directory never executes scripts.|Which component chooses whether this file is data or executable source?`,
`Content types and file signatures|Change the multipart Content-Type while keeping the same file bytes.|The header-only validator accepts the file despite its incompatible contents.|Client-supplied MIME types are claims. Magic bytes and image decoding add checks but polyglots may satisfy one parser while remaining meaningful to another.|Passing an image signature check does not prove an executable handler will process the file.|Which validators run and which interpreter later consumes the stored bytes?`,
`Extensions and path handling|Compare mixed-case, multiple-extension, encoded-name, and path-containing filenames.|A decoding or normalization mismatch changes the final stored filename.|Determine actual server filename and extension handling. Null-byte behavior is legacy-specific; path traversal requires a writable destination and unsafe path construction.|A successful upload response does not establish the filename used on disk.|What name does retrieval confirm after sanitization and normalization?`,
`Upload races|Fetch a file while the modeled service stores it before running antivirus or type validation.|A narrow interval exposes the unvalidated file before deletion.|Quarantine before publication and atomic state transitions close the window. Repeated success requires timing, a known path, and an executable or readable exposure.|A rejected file seen only after deletion does not prove a reachable race window.|At what exact point does the file become reachable relative to validation?`],
deserialization: [`Insecure deserialization`,`Saving an object should be like saving a shopping list. Some formats instead save instructions for rebuilding a machine, including parts that act while being rebuilt.`,
`Identify format and tampering|Decode an object-like session value and change an ordinary role property.|The model restores the modified object without integrity protection.|Serialization turns state into a transferable representation. Integrity, types, and reconstruction behavior matter; not every serialized format invokes code.|Base64-looking input may be opaque random data. Identify the decoded structure before editing.|Does a changed property persist, and is the value authenticated?`,
`Types and magic methods|Change a string field to a boolean, then restore an object with a side-effecting lifecycle method.|The model first changes a loose comparison; object reconstruction triggers a method separately.|Type juggling and object injection are different mechanisms. Magic methods can run during restoration, use, or cleanup depending on language and class.|Changing serialized string length inconsistently may simply corrupt the format.|Which lifecycle event triggers behavior and what input controls its arguments?`,
`Gadget chains and dependencies|Follow a chain of existing classes from restored property to file operation.|The model reaches a dangerous method without adding a new class to the server.|A gadget is existing code used in an unintended sequence. Java, PHP, and Ruby chains depend on exact installed libraries, versions, and reachable entry points.|A published gadget chain fails if the required class is absent or filtered.|What classes and method calls connect the deserialization entry point to the sensitive sink?`,
`Custom chains and PHAR|Trace an application class's cleanup method; compare a PHAR metadata path in a legacy configuration.|The modeled metadata restoration enters the same class chain.|Custom chains require source-level dataflow reasoning. PHAR-triggered automatic metadata deserialization depends on PHP version and the specific API used.|Modern PHP behavior differs; a phar:// path is not a universal deserialization trigger.|Which runtime and filesystem call actually restore metadata here?`],
'prototype-pollution': [`Prototype pollution`,`An object can inherit default settings from a shared family notebook. Pollution writes into that notebook so unrelated objects inherit the attacker's setting.`,
`Own versus inherited properties|Merge an object containing a special prototype-related path, then read a missing property on a fresh object.|The fresh object inherits the injected value in this intentionally vulnerable model.|JavaScript property lookup follows the prototype chain. Unsafe recursive merges or parsers can let input modify a prototype rather than an ordinary own property.|An ordinary property named __proto__ is not always a pollution vector; behavior depends on parser and assignment.|Does a separate object inherit the marker without owning it?`,
`Find a useful gadget|Pollute a default URL property consumed by a later DOM script loader.|The property reaches a script URL sink only when code trusts inherited defaults.|A pollution source plus a gadget plus a dangerous sink produces impact. Finding a polluted property alone does not prove XSS or code execution.|A gadget reading only validated own properties may ignore the polluted value.|What later operation consumes the inherited property?`,
`Alternative vectors and sanitization|Compare __proto__ with a constructor.prototype path through a recursive merge.|A key-blocking filter misses the second inheritance path in the model.|Query parsers, JSON merges, and third-party libraries handle path syntax differently. Sanitization must address recursive structure and inheritance semantics.|One working syntax cannot be assumed to work across every merge library.|Which exact assignment changes the shared prototype in this parser?`,
`Server-side non-destructive detection|Set a harmless response-format default and compare repeated responses.|The modeled indentation changes without reflecting the polluted key.|Server-side pollution can be detected through controlled behavioral changes. State may persist across requests; choose reversible probes and document cleanup.|No reflected key does not mean no pollution. A persistent crash is poor evidence for a precise cause.|Which harmless inherited default changes observable behavior in this server?`,
`Privilege and process gadgets|Follow a polluted authorization default or a process-option object.|The model's inherited default changes a role decision or process configuration.|Server-side impact depends on reachable code paths, object construction, and runtime behavior. Exfiltration or execution requires an additional suitable gadget.|Browser-side gadgets cannot be transplanted directly to a server runtime.|What concrete server operation reads this inherited option, and when?`],
llm: [`Web LLM & agent attacks`,`An assistant may read a document and also hold a key to a filing cabinet. The dangerous mistake is letting instructions inside that document decide how the key is used.`,
`Tools and excessive agency|Ask a modeled assistant to perform a privileged tool action outside the user's permissions.|A tool lacking its own authorization accepts the request.|The security boundary belongs at the tool and application layer. A prompt telling the model to be careful cannot replace permissions on each action.|A model agreeing in text is not evidence that any privileged operation occurred.|What independently observable tool effect proves the boundary failed?`,
`Indirect prompt injection|Place an instruction in a retrieved review that the assistant summarizes.|The flawed model treats lower-trust document text as an instruction to call a tool.|Separate user intent, developer instructions, and retrieved data. Indirect injection arrives through a lower-trust source such as a page, email, or tool result.|A malicious document existing is not enough; the agent must retrieve and act on it.|Which trust level supplied the instruction that caused the tool call?`,
`Insecure output handling|Let the assistant return attacker-influenced HTML that an application inserts as markup.|The application sink turns model output into active content.|LLM output is untrusted data. XSS, SQL injection, and command injection can occur when output is passed into interpreters without context-appropriate handling.|A harmless model text response does not execute until a downstream component interprets it.|Which application sink turns generated text into executable instructions?`,
`Agent chains and data movement|Follow a retrieved page instruction into a second tool that sends account data to an external destination.|The modeled tool log shows both a private read and an unauthorized outbound write.|Analyze source, tool authority, secrets, destination restrictions, and user-approved task. A chain can cross several independent boundaries, including a secondary web bug.|A claim of exfiltration in generated text is weaker than an actual correlated outbound action.|Where must authorization and destination checks stop this chain?`,
`Defense evaluation with evidence|Compare a blocked direct instruction with the same requested action hidden in retrieved material.|One phrasing is rejected while a different trust path still reaches the tool.|Evaluate actual permissions and tool traces across direct and indirect inputs. Filtering words is not a durable authority boundary.|A single failed prompt proves only that attempt failed; it does not establish secure tool design.|What invariant should hold regardless of the words used in retrieved content?`],
'host-header': [`HTTP Host header attacks`,`A receptionist may ask which company you are visiting in a shared building. Your answer should choose a route, not certify your identity or define trusted links.`,
`Password reset poisoning|Change Host on a password-reset request while keeping the account fixed.|The modeled reset email contains a link to the supplied host.|Absolute URL generation must use a configured trusted origin. X-Forwarded-Host and similar overrides matter only when the application trusts them.|An attacker-host link is useful only if the delivered reset token reaches an attacker-controlled destination.|Which response or email proves the reset link uses the untrusted host?`,
`Routing and authentication|Compare an internal-looking Host with the public host on the same network connection.|The model routes to an internal service or grants an internal-only role.|The Host header can influence routing but should not establish client trust. Absolute request targets, duplicate headers, and ports can trigger parsing disagreements.|A host being accepted does not prove an internal service is reachable.|Which service answered and what permission changed?`,
`Ambiguity and cache interaction|Send a request with differing routing and URL-generation host values.|The model caches a response influenced by a host value absent from its cache key.|When components choose different host values, routing, link generation, and caching can disagree. Trace each interpretation separately.|Duplicate Host headers are often rejected; behavior is server-specific.|Which host does the cache key use and which host does the origin render?`,
`Connection state and chained impact|Use one accepted host on the first request, then a different host on a reused connection.|The flawed model applies a cached first-request trust decision to the next request.|Connection-level routing assumptions must not replace per-request validation. Dangling-markup reset attacks add a separate HTML leakage mechanism.|A new TCP connection per request will not reproduce a connection-state flaw.|What security decision is wrongly reused across requests?`],
'cache-poisoning': [`Web cache poisoning`,`A shared photocopier keeps one copy of a page for everyone. Poisoning makes it save your altered copy under the label used by ordinary visitors.`,
`Cache keys and unkeyed inputs|Change a forwarded host header while requesting a unique test URL, then fetch without that header.|The cache serves the altered response to the clean request.|A cache key decides which requests share a response. Poisoning needs attacker-controlled response influence that is absent from the key, plus cacheability and a reachable victim request.|Reflection without shared reuse is not cache poisoning. Test with isolated cache keys and inspect age or cache-hit signals.|Can a clean request retrieve your unique marker from a stored response?`,
`Cookies, query fields, and cloaking|Compare a parameter the origin uses with the subset the cache includes in its key.|Two requests share a cache entry even though the origin would render different content.|Unkeyed cookies, entire query strings, selected query fields, and duplicate-parameter cloaking can produce mismatched interpretations.|Adding a cache-buster changes the key; use the same isolated key for poison and clean retrieval.|Which parameter does the origin interpret that the cache ignores?`,
`Fat GET and normalization|Send a GET body or an encoded path variant that changes origin output without changing the cache key.|The modeled cache stores the altered response under the normalized resource.|Some origins consume GET bodies while caches ignore them. Path and query normalization differences can merge requests with different meanings.|Many intermediaries reject GET bodies or normalize identically; verify behavior.|What exact byte difference disappears from the cache's key but survives at the origin?`,
`Gadgets and strict cacheability|Poison a cached script location consumed by a separate DOM gadget.|A stored response causes a later browser page to load the altered resource.|Impact may require two resources, multiple headers, strict cacheability rules, or a chain of caches. Prove storage, delivery, and the victim-side sink independently.|A cacheable redirect or marker does not by itself establish script execution.|Which later browser operation turns the poisoned bytes into security impact?`,
`Cache key injection and internal caches|Place a delimiter into a value used by a custom internal cache key.|The model confuses two logical resources with the same constructed key.|Key serialization must be unambiguous. Internal application caches may have different keys and lifetime rules from the public CDN.|An edge-cache miss does not reveal whether an internal cache was hit.|Which cache layer stored the value, and what evidence identifies its key collision?`],
'cache-deception': [`Web cache deception`,`A librarian sees a book jacket marked “public brochure” and shelves a private diary there. Deception tricks the cache about whether a private response is static public content.`,
`Path mapping and static rules|Request /account/extra.css while logged in, then fetch the same path without a session.|The origin maps it to the account page while the cache stores it as a static stylesheet path.|Deception stores private content under an attacker-chosen path. Poisoning instead makes attacker-influenced content reach ordinary requests; the two mechanisms differ.|A path returning the account page is not enough if the response is never cached publicly.|Can an unauthenticated second session retrieve the first session's private marker?`,
`Delimiter disagreement|Compare /account;extra.css with /account/extra.css.|The origin stops parsing at a delimiter the cache treats as part of a static path.|Framework path delimiters differ. Identify where the origin stops mapping and what extension or prefix the cache uses to classify a response.|A delimiter meaningful in one framework may be literal or rejected elsewhere.|Where do cache and origin disagree about the end of the resource path?`,
`Normalization differences|Compare encoded dot segments in paths interpreted differently by edge and origin.|One layer normalizes to an account route while the other sees a cacheable static path.|Determine which layer decodes or removes path segments first. Both origin-side and cache-side normalization can create dangerous mismatches.|A browser may normalize your path before sending it; inspect the actual wire request.|Which path bytes arrive at each layer before normalization?`,
`Exact-match rules and delivery|Use a path variant that the cache treats as an exact public resource but the origin maps privately.|The modeled private page is stored under an otherwise trusted cache key.|Exact-match rules can still be unsafe if parsers disagree. A practical chain needs victim delivery, an authenticated response, storage, and subsequent retrieval.|Testing only with your own cached public data misses the privacy boundary.|What proves that the retrieved response belongs to another session rather than your own browser cache?`],
'request-smuggling': [`HTTP request smuggling`,`Two clerks split the same stack of papers into different orders. If they disagree where one order ends, the next customer's papers can be attached to yours.`,
`CL.TE and TE.CL boundaries|Give a teaching proxy a body with both Content-Length and chunked Transfer-Encoding; switch which boundary each side uses.|The front end and back end consume different byte ranges.|CL.TE means the front end uses length and the backend uses chunking; TE.CL reverses them. Exact bytes and connection reuse determine desynchronization.|A parser error or timeout alone is not confirmation; malformed requests can simply be rejected.|Which bytes remain queued after each component considers the request complete?`,
`Header obfuscation and confirmation|Compare a rejected duplicate-length request with a transfer-encoding variant interpreted by only one layer.|The modeled next request receives a differential response after leftover bytes are consumed.|Ambiguous header handling can expose framing disagreement. Use lab-isolated repeated differential tests and preserve exact request bytes.|A clean separate connection cannot demonstrate contamination of a reused backend connection.|What paired sequence distinguishes queued-byte contamination from an ordinary bad request?`,
`Bypass and request capture|Place a second modeled request behind a front-end-approved request.|The backend processes an internal route that the front end never separately authorizes.|Desynchronization can bypass edge rules, reveal rewrites, capture appended requests, or deliver XSS. Each impact needs an additional reachable backend behavior.|A framing mismatch does not automatically grant access to every internal route.|Which security rule exists only at the layer that misses the hidden request?`,
`HTTP/2 downgrade and CRLF|Compare an HTTP/2 request's framed body with an injected length or newline forwarded into HTTP/1.|The downgrade model serializes a different HTTP/1 message than the edge validated.|HTTP/2 has explicit framing, but translation can reintroduce H2.CL, H2.TE, header injection, or request splitting. Inspect the translated request and reject forbidden header bytes.|HTTP/2 support alone does not imply a vulnerable downgrade.|What new HTTP/1 syntax appears only when the HTTP/2 request is translated?`,
`Response queues and tunnelling|Cause the model to produce two backend responses for one front-end request.|The next modeled user receives a response intended for a different request.|Queue poisoning misaligns response assignment. Tunnelling can expose hidden backend responses on a connection without ordinary cross-user reuse; prove which behavior you have.|One unusual response is weaker than a reproducible queue sequence with distinct markers.|How many backend responses exist and which front-end request receives each one?`,
`CL.0, 0.CL, and browser desync|Compare a backend ignoring a request body with a front end that forwards it using Content-Length.|Leftover body bytes become the start of another request in the model.|CL.0 and 0.CL describe zero-versus-length disagreements. Browser-compatible client-side desync has additional request restrictions and depends on browser connection reuse.|Classic raw TE payloads cannot necessarily be sent by browser JavaScript.|Can a real browser deliver the framing condition and reuse the affected connection?`,
`Pause-based and cache chains|Pause a partial body in a model with different timeout behavior; then trace a poisoned response into a cache.|One side commits early while the other continues reading, enabling a second desynchronization path.|Timing, early responses, and reuse can produce pause-based or double-desync chains. Cache poisoning and deception add separate key and storage requirements.|Changing timing without measuring connection state cannot establish a reliable smuggling primitive.|Which timeout or early-response event changes the parser state at each hop?`],
'race-conditions': [`Race conditions`,`Two cashiers both check the same last coupon before either marks it used. Each follows the rule alone, but together they spend it twice.`,
`Check then act|Run two modeled coupon requests sequentially, then interleave both checks before either write.|Sequential use allows one discount; interleaving allows two.|A limit overrun is possible when validation and state change are not atomic. The critical interval is between the check and the committed write.|Fast sequential requests can miss a very short window.|What shared state must both requests observe before either changes it?`,
`Synchronize and control|Compare deliberately staggered requests with requests released together.|The simultaneous group triggers more duplicate successes in the model.|Synchronization reduces arrival jitter. Connection warming, last-byte synchronization, or HTTP/2 single-packet approaches depend on the target and tools.|A single extra success could be eventual consistency or a retry artifact; reproduce and inspect state.|What control shows that overlap, rather than the request count alone, caused the effect?`,
`Multi-endpoint and sub-states|Interleave account creation with an endpoint that assumes the account is already fully initialized.|The model exposes a brief state where a token or role is unset.|Races can span endpoints and partial construction, not only repeated calls. Map hidden sub-states and when identity, token, and permissions are written.|A permanent logic bug can resemble a race; compare the same request after construction completes.|Which intermediate state exists only before the final initialization write?`,
`Time-sensitive tokens and limits|Trigger parallel token generations that use the same timestamp-based value.|The model produces correlated tokens or bypasses a non-atomic counter.|Time-sensitive collisions differ from coupon overruns but still involve shared time or state. Measure actual token relationships and counter updates.|Two requests happening close together do not imply equal secure random tokens.|Which deterministic input or shared counter makes simultaneous execution security-sensitive?`],
'essential-skills': [`Tools & efficient testing`,`A scanner is a metal detector, not a verdict. You still choose the ground, separate signal from noise, and verify what it finds.`,
`Map before scanning|Capture one complete user workflow and identify its writable fields and privileged transitions.|The scan scope becomes a small set of relevant requests instead of every static asset.|Browse, proxy, replay, and map roles first. Burp's browser and Repeater provide manual control; automated scanning is tool- and license-dependent.|No scanner result does not mean a workflow or authorization boundary is safe.|Which captured request is most likely to reach a new parser or sensitive state change?`,
`Insertion points and nested formats|Locate a base64-encoded JSON field inside an outer form body and change only an inner value.|The application reaches the inner parser when the outer encoding remains valid.|A scanner needs meaningful insertion points. Preserve wrappers, checksums where understood, and syntax so mutations reach the intended sink.|Corrupting the outer format only tests its decoder and can hide the deeper attack surface.|What exact transformations carry the chosen inner field to its final sink?`,
`Validate and minimize findings|Reproduce a scanner alert with one minimal request and an unsuccessful control.|The finding survives outside the automated tool with a clear response difference.|Automated labels are hypotheses. Rule out reflection, cache artifacts, stale state, and unrelated errors before writing a finding.|A severity label cannot substitute for demonstrated access or an executed action.|What is the smallest request pair that proves the security boundary failure?`],
fieldcraft: [`CTF fieldcraft & exploit chains`,`A challenge is a trail of connected clues, not a vending machine for one famous payload. The next useful move is the one that resolves uncertainty.`,
`Unknown-vulnerability triage|Start with an unlabeled app and inventory inputs, roles, parsers, network fetches, and state transitions.|Each feature suggests a small set of competing hypotheses.|Use capabilities to choose tests: file access suggests path handling; remote fetches suggest SSRF; object IDs suggest authorization. Observe before choosing a vulnerability name.|Spraying every payload into every field produces noise and can destroy useful state.|Which feature gives the strongest evidence for the first controlled experiment?`,
`Build a chain with prerequisites|Connect source disclosure to a parser hypothesis, then to an authenticated action.|Each step supplies a capability required by the next step.|Write a capability graph: what you control, what you can observe, and what each step grants. A chain is valid only if all prerequisites and trust crossings are shown.|Two separate vulnerabilities do not form a chain unless output from one enables the other.|What specific capability does step one provide that step two requires?`,
`When a test fails|A candidate payload returns 403 while a benign marker reaches the response.|The parser may be reachable even though that payload was blocked.|Separate transport, authentication, validation, parsing, sink reachability, and impact. Change one assumption at a time and record negative evidence.|Repeating the same payload with random encodings is not progress without a decoding hypothesis.|Which observation would tell you whether the block occurs before or after the vulnerable sink?`,
`Explain and retain the result|Write a short finding with boundary, request pair, observed impact, and root-cause fix.|A later solver can reproduce the proof without memorizing the original payload.|After solving, change one condition and predict whether the exploit survives. Revisit weak skills in spaced sessions; a solved flag does not prove transferable mastery.|Reading the solution and marking solved can conceal a missing mental model.|What variant would fail after the proposed fix and what regression should remain blocked?`]
}
export const modules = Object.entries(content).map(([id, rows])=>{
 const [title,analogy,...baseLessons]=rows
 const lessons=[...baseLessons,...(advancedRows[id]||[])]
 const stage=stages.find(s=>s.ids.includes(id))
 return {id,title,analogy,stage:stage.id,source: catalog.topics.find(t=>t.slug===id)?.labs[0]?.url.split('/lab-')[0] || 'https://portswigger.net/web-security/learning-paths',lessons:lessons.map((row,i)=>{
 const [title,change,evidence,mechanism,limit,transfer]=row.split('|')
 return {id:`${id}:${i}`,title,change,evidence,mechanism,limit,transfer}
 })}
})
export const lessonCount=modules.reduce((n,m)=>n+m.lessons.length,0)
export const legacyTopicIds=Object.fromEntries(catalog.topics.map(t=>[t.id,t.slug]))
export const academyLabs=catalog.topics.flatMap(t=>t.labs.map(l=>({...l,module:t.slug})))
// Stable, explicitly authored preparation records replace title inference.
export function preparation(lab){
 const ids=preparationMap[lab.id]?.skills||[]
 return ids.map(id=>modules.flatMap(m=>m.lessons).find(l=>l.id===id)).filter(Boolean)
}
export function ownerOfLesson(id){return modules.find(m=>m.lessons.some(l=>l.id===id))}
