export const terms=[
['Request','A message your browser sends asking a server to do or return something.'],['Response','The server’s reply: a status, headers, and usually a body.'],['Header','A named metadata field in an HTTP request or response.'],['Cookie','A browser-stored value attached automatically to matching requests.'],['Session','Server-recognized state linking requests to a login or workflow.'],['Origin','The combination of scheme, hostname, and port used by browser isolation.'],['Site','A scheme and registrable-domain grouping used by SameSite cookie rules.'],['Parser','Code that gives structure and meaning to a sequence of bytes.'],['Sink','The operation that finally uses input, such as rendering HTML or opening a file.'],['Source','The place untrusted data enters a program.'],['Encoding','A different representation of bytes; it does not inherently hide or authenticate them.'],['Authentication','Checking which identity is making a request.'],['Authorization','Checking whether that identity may perform this action on this resource.'],['Trust boundary','A point where data or authority moves between different levels of trust.'],['Payload','The specific input used in a controlled test.'],['Baseline','The normal request and response against which you compare a change.'],['Oracle','An observable signal that answers a hidden question, sometimes just one bit at a time.'],['Out-of-band','Evidence arriving through a separate channel, such as a correlated DNS callback.'],['CSRF token','An unpredictable request value validated to distinguish intended actions from forged ones.'],['CSP','Content Security Policy: browser rules restricting resource loading and script execution.'],['CORS','Cross-Origin Resource Sharing: response rules controlling cross-origin browser reads.'],['DOM','The browser’s live object representation of a document.'],['JWT','JSON Web Token: claims in a structured token, commonly protected by a signature or MAC.'],['HMAC','A keyed integrity check where the signer and verifier share a secret.'],['Gadget','Existing code whose behavior becomes useful in an unintended exploit chain.'],['Prototype','An object from which another JavaScript object can inherit properties.'],['Cache key','The request attributes used to choose a stored response.'],['Atomic','A state change that completes as one indivisible operation relative to competing work.'],['SSRF','Server-side request forgery: attacker-influenced network requests made by a server.'],['XXE','XML external entity injection: unsafe XML processing expands attacker-influenced external resources.'],['SSTI','Server-side template injection: input becomes executable template source.'],['XSS','Cross-site scripting: attacker-influenced script executes in another user’s page context.'],['CSRF','Cross-site request forgery: a browser is induced to perform an unintended authenticated action.'],['TOCTOU','Time of check to time of use: a gap between validating state and acting on it.'],['PKCE','Proof Key for Code Exchange: binds an OAuth authorization code to a verifier held by the initiating client.'],['DTD','Document Type Definition: XML declarations that can define entities and structure.'],['MIME type','A label describing content, such as image/png; a client-provided label is not proof of file contents.'],['Resolver','GraphQL code that supplies the value for a requested field.']
]
terms.push(
['Database','A service that stores structured records and answers queries about them.'],
['Query','A structured request for data or an operation, interpreted by a database or API.'],
['Endpoint','A particular application route and operation you can call with a request.'],
['Proxy','An intermediary that receives and forwards requests; a testing proxy lets you inspect or replay them.'],
['Repeater','Burp’s tool for editing and resending a captured request one experiment at a time.'],
['Intruder','Burp’s tool for sending controlled sets of request variations; capabilities depend on edition.'],
['Payload position','The precise input location you choose to vary in a captured request.'],
['Schema','The expected structure, field names, and value types of data.'],
['Resolver','GraphQL code that supplies a requested field and must enforce the relevant permissions.'],
['Introspection','GraphQL’s built-in way to ask about a schema’s types and fields.'],
['Alias','A GraphQL result name that lets an operation request a field more than once under different names.'],
['Metadata','Information describing other data, a resource, or an operation. It can still be untrusted input.'],
['Literal','A value interpreted as data, such as a number or quoted string, rather than as a new instruction.'],
['Predicate','A condition whose result is true or false. A blind channel can reveal that one bit.'],
['Dialect','A particular implementation’s version of a language, with its own syntax and functions.'],
['UNION','A SQL operation combining compatible result rows from more than one query.'],
['Parameter binding','Supplying query values separately from query source so values do not rewrite its grammar.'],
['Serialization','Turning structured state into bytes that can be stored or transferred.'],
['Deserialization','Reconstructing data or objects from a stored representation. Some object formats can trigger behavior.'],
['Canonical path','The resolved path after relevant decoding and dot-segment handling. It must still be checked against an allowed root.'],
['Containment','A policy requiring a resolved file or resource to remain inside an allowed boundary.'],
['Egress','Network traffic leaving a server or environment. Egress restrictions can block an external callback.'],
['Loopback','An address such as 127.0.0.1 that refers back to the machine making the connection.'],
['DNS','Domain Name System: turns a hostname into addresses and other records used to locate services.'],
['Nonce','An unpredictable value used in a specific context; a CSP nonce authorizes particular script elements.'],
['Sandbox','A restricted environment or policy that limits the capabilities code can use. Its exact rules matter.'],
['Gadget chain','A sequence of existing code paths joined to turn controlled data into a sensitive action.'],
['Lifecycle method','Code run automatically during an object’s restoration, use, or cleanup.'],
['Own property','A property stored directly on an object, rather than inherited from its prototype.'],
['HMAC','A keyed integrity check using a secret shared by the creator and verifier.'],
['Public key','The shareable half of an asymmetric key pair, used to verify signatures or encrypt to its owner.'],
['Signature','A cryptographic check over exact bytes. Meaningful trust also depends on choosing the right verification key and policy.'],
['Issuer','The authority that created a token; the application must verify it is an issuer it trusts.'],
['Audience','The intended recipient of a token. A valid token for another application should not automatically be accepted here.'],
['State machine','A set of permitted application states and rules for moving between them.'],
['Critical window','The interval in which overlapping operations can observe stale shared state.'],
['Race','A result that changes because operations overlap or execute in an unexpected order.'],
['Cacheability','The rules deciding whether and how a response can be stored for later reuse.'],
['Normalization','Transforming different representations into a standard form. Components that normalize differently can disagree.'],
['Content-Length','An HTTP header stating a message body’s length in bytes; framing discrepancies can be dangerous.'],
['Transfer-Encoding','An HTTP/1.1 field describing transfer coding such as chunked framing.'],
['Downgrade','Translation from a newer protocol such as HTTP/2 into another protocol such as HTTP/1.1.'],
['Framing','The rules identifying where a message begins and ends on a connection.'],
['CSP nonce','A per-response unpredictable value authorizing specific scripts under a Content Security Policy.'],
['HttpOnly','A cookie attribute preventing direct JavaScript access to that cookie’s bytes.'],
['SameSite','A cookie attribute restricting selected cross-site delivery; it is different from same-origin isolation.'],
['Mass assignment','An object update that accepts fields the caller should not be allowed to modify.'],
['Polyglot','One sequence of bytes with meaningful interpretations in more than one file format or language.']
)
// Keep one clear definition per term.
for(let i=terms.length-1;i>=0;i--)if(terms.findIndex(t=>t[0].toLowerCase()===terms[i][0].toLowerCase())!==i)terms.splice(i,1)
